// МЕГА №2: пульт — OLED + кнопки без фиксации, связь с приёмником по Serial1
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_SSD1306 display(128, 64, &Wire, -1);
#define OLED_ADDR 0x3C

const uint8_t BTN_UP   = 2;   // канал +
const uint8_t BTN_DOWN = 3;   // канал -
const uint8_t BTN_SCAN = 4;   // автоскан

const uint16_t FREQ[8][8] = {
  {1920,1960,2000,2040,2080,2120,2160,2200},
  {1900,1940,1980,2020,2060,2100,2140,2180},
  {1740,1760,1780,1800,1820,1840,1860,1880},
  {1720,1740,1760,1780,1800,1820,1840,1860},
  {1420,1460,1500,1540,1580,1620,1660,1700},
  {1400,1440,1480,1520,1560,1600,1640,1680},
  {1100,1140,1180,1220,1260,1300,1340,1380},
  {1080,1120,1160,1200,1240,1280,1320,1360},
};

uint8_t channel = 0;
int rssi = 0;
bool linkOk = false;
unsigned long lastLink = 0, tRssi = 0;
uint8_t lastU = HIGH, lastD = HIGH, lastS = HIGH;

uint16_t freqOf(uint8_t ch) { return FREQ[ch / 8][ch % 8]; }

void sendCmd(char c) { Serial1.write(c); }

void draw() {
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(3); display.setCursor(0, 0);
  display.printf("CH %02u", channel);
  display.setTextSize(1); display.setCursor(0, 30);
  display.printf("FR%u  CH%u   %u MHz\n",
                 (channel - 1) / 8 + 1, (channel - 1) % 8 + 1, freqOf(channel - 1));
  display.setCursor(0, 52);
  display.printf("%s RSSI %4d", linkOk ? "LINK" : "----", rssi);
  int bar = map(rssi, 0, 1023, 0, 50);
  display.drawRect(78, 52, 50, 9, SSD1306_WHITE);
  display.fillRect(79, 53, bar > 0 ? bar - 1 : 0, 7, SSD1306_WHITE);
  display.display();
}

void scanRequest() {
  sendCmd('S');
  display.clearDisplay(); display.setTextSize(2); display.setCursor(0, 24);
  display.print("Scanning..."); display.display();
}

void setup() {
  Serial.begin(115200);
  Serial1.begin(9600);
  pinMode(BTN_UP, INPUT_PULLUP);
  pinMode(BTN_DOWN, INPUT_PULLUP);
  pinMode(BTN_SCAN, INPUT_PULLUP);
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) { Serial.println(F("OLED?")); for(;;); }
  draw();
}

void loop() {
  // Кнопки: короткое нажатие — шаг канала, скан — по своей кнопке
  uint8_t u = digitalRead(BTN_UP), d = digitalRead(BTN_DOWN), s = digitalRead(BTN_SCAN);
  static unsigned long tU = 0, tD = 0, tS = 0;
  if (u == LOW && lastU == HIGH && millis() - tU > 150) { sendCmd('U'); tU = millis(); }
  if (d == LOW && lastD == HIGH && millis() - tD > 150) { sendCmd('D'); tD = millis(); }
  if (s == LOW && lastS == HIGH && millis() - tS > 300) { scanRequest(); tS = millis(); }
  lastU = u; lastD = d; lastS = s;

  // Приём телеметрии: "C<n> R<rssi>"
  while (Serial1.available()) {
    char c = Serial1.read();
    static char mode = 0; static long num = 0;
    if (c == 'C' || c == 'R') { mode = c; num = 0; }
    else if (c >= '0' && c <= '9') num = num * 10 + (c - '0');
    else if (c == '\n') {
      if (mode == 'C' && num >= 1 && num <= 64) channel = num;
      else if (mode == 'R') rssi = num;
      mode = 0;
    }
    lastLink = millis();
  }
  linkOk = (millis() - lastLink < 1000);   // связь считаем живой, если данные идут

  if (millis() - tRssi > 100) { tRssi = millis(); draw(); }
}
